WITH valid AS (SELECT *, revenue * units AS revenue_per_unit FROM store_sales WHERE sale_date > DATE '2023-04-04' AND YEAR(sale_date) >= 2023), with_windows AS (SELECT *, LEAD(units) OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS next_units, LAG(units) OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS prev_units, LEAD(revenue_per_unit) OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS next_revenue_per_unit, LAG(revenue_per_unit) OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS prev_revenue_per_unit, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS event_seq FROM valid), base AS (SELECT id, store_id, sale_date, units, revenue, revenue_per_unit, prev_units, prev_revenue_per_unit, event_seq, DATEDIFF(CURRENT_DATE(), sale_date) AS days_since_sale_date, CEIL(prev_units) AS prev_units_whole FROM with_windows WHERE sale_date > DATE '2023-08-31' AND next_revenue_per_unit < 47), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY units DESC NULLS LAST, id) AS dedup_rank FROM base QUALIFY dedup_rank = 1) SELECT store_id, DATE_TRUNC('MONTH', sale_date) AS activity_month, COUNT(*) AS num_rows, ROUND(AVG(days_since_sale_date), 2) AS avg_days_since_sale_date, ROUND(AVG(event_seq), 2) AS avg_event_seq, ROUND(AVG(event_seq), 2) AS avg_event_seq_2, RANK() OVER (PARTITION BY store_id ORDER BY ROUND(AVG(days_since_sale_date), 2) DESC) AS avg_days_since_sale_date_rank FROM ranked GROUP BY store_id, DATE_TRUNC('MONTH', sale_date);
